raw_commands:
{%- macro t(value) -%}{{ (value or "") | string | replace('"', "'") }}{%- endmacro -%}
{%- macro left(code) -%}
QRCODE 542,271,L,10,A,180,M2,S7,"{{ code }}"
TEXT 514,55,"ROMAN.TTF",180,1,12,"{{ code }}"
{% endmacro -%}
{%- macro right(code) -%}
QRCODE 254,271,L,10,A,180,M2,S7,"{{ code }}"
TEXT 226,55,"ROMAN.TTF",180,1,12,"{{ code }}"
{% endmacro -%}
{#- two labels across: an odd label waits in ns.pending and pairs with the next item -#}
{%- set ns = namespace(pending=none) -%}
SIZE 73.5 mm, 38 mm
GAP 3 mm, 0 mm
DIRECTION 0,0
REFERENCE 0,0
OFFSET 0 mm
SET PEEL OFF
SET CUTTER OFF
SET PARTIAL_CUTTER OFF
SET TEAR ON
CODEPAGE 1252
CLS
{% for row in doc.items if row.qty -%}
{%- set code = t(row.barcode or row.item_code) -%}
{%- set qty = row.qty | int -%}
{%- if ns.pending -%}
{{ left(ns.pending) }}{{ right(code) }}PRINT 1,1
CLS
{% set qty = qty - 1 -%}
{%- set ns.pending = none -%}
{%- endif -%}
{%- if qty // 2 -%}
{{ left(code) }}{{ right(code) }}PRINT 1,{{ qty // 2 }}
CLS
{% endif -%}
{%- if qty % 2 -%}{%- set ns.pending = code -%}{%- endif -%}
{%- endfor -%}
{%- if ns.pending -%}
{{ left(ns.pending) }}PRINT 1,1
CLS
{% endif -%}
